const $=id=>document.getElementById(id),colours=['#378bdb','#ef6058','#e7b942','#9b6dd6'];
const CAM=[154,-202,180],TARGET=[0,0,3],ppm=1200/225;
const normal=v=>{let n=Math.hypot(...v);return v.map(x=>x/n);},cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
