 function frame(now){requestAnimationFrame(frame);let dt=Math.min(.1,(now-last)/1000);last=now;if(battle.status==='playing'&&!paused){let sx=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+joy.x,sy=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)+joy.y,len=Math.max(1,Math.hypot(sx,sy));sx/=len;sy/=len;acc+=dt;while(acc>=1/60){battle.update(1/60,{x:right[0]*sx+right[1]*sy,y:right[1]*sx-right[0]*sy,fire:fire||keys.has('Space')});acc-=1/60;}events();}if(toastT>0){toastT-=dt;if(toastT<=0)$('toast').classList.remove('show');}frames++;ft+=dt;if(ft>1){$('perf').textContent=Math.round(frames/ft)+' FPS · 相容模式';frames=0;ft=0;}ui+=dt;if(ui>.1){uiUpdate();ui=0;}draw(dt);}
 function restart(){battle.reset();keys.clear();joy.x=joy.y=0;fire=false;acc=0;begin();}
 $('teamhud').innerHTML=TEAM_NAMES.map((n,i)=>'<div class="teamcard" id="team'+i+'" style="--team:'+colours[i]+'"><strong>'+n+'<span>1800</span></strong><div class="bar"><i></i></div></div>').join('');$('start').disabled=false;$('start').textContent='單機遊玩（相容模式）→';$('start').onclick=begin;$('loadline').firstElementChild.style.width='100%';$('welcome').querySelector('.intro-foot').firstElementChild.textContent='相容模式 · 玩法測試';let noteEl=document.createElement('p');noteEl.className='controls-note';noteEl.textContent='此裝置未提供 WebGL。相容模式使用立體場景預覽＋2.5D 人物；完整 3D 需支援 WebGL 2。';$('welcome').querySelector('.intro-card').append(noteEl);document.body.dataset.renderMode='compatibility';
 $('resume').onclick=resume;$('pause').onclick=pause;$('restart').onclick=restart;$('restartPause').onclick=restart;$('interact').onclick=()=>{if(!paused)battle.interact();};$('command').onclick=()=>{if(!paused){battle.mode=battle.mode==='follow'?'attack':'follow';note(battle.mode==='follow'?'隊友集合，跟隨你行動':'隊友主動搜集補給及出擊');}};for(let b of document.querySelectorAll('[data-craft]'))b.onclick=()=>{if(!paused)battle.craft(b.dataset.craft);};$('overview').onclick=()=>{overview=!overview;$('overview').textContent=overview?'跟隨':'全圖';};$('zoomin').onclick=()=>{overview=false;zoom=clamp(zoom-6,25,90);};$('zoomout').onclick=()=>zoom=clamp(zoom+6,25,90);$('sound').onclick=()=>{sound=!sound;$('sound').style.opacity=sound?1:.4;};$('quality').textContent='畫面：相容模式';$('quality').onclick=()=>note('此裝置未提供 WebGL，已使用相容畫面。');
 addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'){if(paused)resume();else pause();return;}if(paused||battle.status!=='playing')return;keys.add(e.code);if(!e.repeat){if(e.code==='KeyE')battle.interact();if(e.code==='Digit1')battle.craft('weapon');if(e.code==='Digit2')battle.craft('buddy');if(e.code==='Digit3')battle.craft('tank');if(e.code==='KeyQ')battle.cycleMode();}});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();if(battle.status==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&battle.status==='playing')pause();});
 let j=$('joystick');function move(e){let r=j.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,rad=r.width*.33,k=Math.max(1,Math.hypot(dx,dy)/rad);joy.x=dx/k/rad;joy.y=dy/k/rad;$('joyknob').style.transform='translate('+dx/k+'px,'+dy/k+'px)';}j.onpointerdown=e=>{if(joy.id!==null)return;joy.id=e.pointerId;j.setPointerCapture(e.pointerId);move(e);};j.onpointermove=e=>{if(joy.id===e.pointerId)move(e);};for(let ev of ['pointerup','pointercancel','lostpointercapture'])j.addEventListener(ev,e=>{if(joy.id===e.pointerId){joy.id=null;joy.x=joy.y=0;$('joyknob').style.transform='';}});for(let el of [$('fire'),canvas]){el.onpointerdown=e=>{if(battle.status==='playing'&&!paused){fire=true;el.setPointerCapture(e.pointerId);}};for(let ev of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(ev,()=>fire=false);}
 bindBuildControls(battle,()=>{keys.clear();fire=false;});bindOnline(battle);resize();addEventListener('resize',resize);uiUpdate();requestAnimationFrame(frame);
